entries[456550] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nBrute Force Idol\nWhen Brann calls for it, jumping on him will cause him to hurl players into their enemies, knocking and dealing significant Physical damage split between them.\n\nYou already have this curio in your collection." }
entries[456551] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nIdol of the Earthmother\nBrann's spells and abilities have a chance to awaken the idol, shielding an injured player for 15 % of their missing health.\n\nYou already have this curio in your collection." }
entries[456552] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nUnbreakable Iron Idol\nWhen any player's health falls below 40 % health during combat, the idol awakens dealing moderate Physical damage to nearby enemies and taunting them for 4 sec. Can only occur every 2 min.\n\nYou already have this curio in your collection." }
entries[456553] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nLight-Touched Idol\nWhen any player uses a defensive ability with a cooldown of 30 sec or longer, the idol activates and heals them for ( 100 / 100)% of their maximum health every 1 sec for 10 sec.\n\nYou already have this curio in your collection." }
entries[456554] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nStreamlined Relic\nWhile out of combat, the party's movement speed is increased by 10 %. Upon entering combat, the party's haste is increased by 5 % for 8 sec.\n\nYou already have this curio in your collection." }
entries[456555] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nIdol of Final Will\nDuring combat, Brann designates a player to guide his shot for 4 sec before firing towards their location and dealing moderate Physical damage to the first enemy hit.\n\nYou already have this curio in your collection." }
entries[456556] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nAmorphous Relic\nUpon entering combat, players gain either Massive or Miniature until combat ends.\n\nMassive\nIncreases your size by 20 %, maximum health by 5 %, and damage and healing done by 3 %.\n\nMiniature\nReduces your size by 20 %, increases movement speed by 5 %, and your haste by 3 %.\n\nYou already have this curio in your collection." }
entries[456557] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nTime Lost Relic\nBrann's spell and abilities have a chance to create bursts of energy, warping the flow of time for all nearby units by 15 % for 12 sec.\n\nCasting, movement, periodic effects, cooldowns, and attack speeds are affected while time warped.\n\nYou already have this curio in your collection." }
entries[456558] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nOlden Seeker Relic\nWhen Brann uses Gathering Tools , there is a 20 % chance to unearth a powerful artifact that grants your party a powerful Boon.\n\nGathering Tools\nBrann uses his gathering tools to help players find additional gold, ore, herbs, fish, leathers, and treasures.\n\nYou already have this curio in your collection." }
entries[456559] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nLifeless Necrotic Relic\nThe idol draws upon unholy energy to prevent fatal damage on players, instead healing them for an amount equal to 100 % of their maximum health and turning them Undead.\n\nWhile Undead, they cannot be healed, lose 14 % of their maximum health every 1 sec, and gain 6 % damage and healing done.\n\nYou already have this curio in your collection." }
entries[456560] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nRelic of Sentience\nWhen a Steel Trap is activated, there is a chance for Brann to throw an additional trap.\n\nYou already have this curio in your collection." }
entries[456561] = { ["name"] = "Adding", ["text"] = "1.5 sec cast\nReagents:\nRelicblood of Zekvir\nRandomly while in combat a bloodbeast will attach itself to Brann, periodically launching morsels of itself near players, granting Bloodstained Blessing upon walking through them.\n\nBloodstained Blessing\nIncreases damage and healing done by 1%, and reduces maximum health by 5% for 1 min.\n\nYou already have this curio in your collection." }
