entries[456587] = { ["name"] = "Royal Chum", ["text"] = "12 - 15 yd range\nInstant\nThrow this fish back into the water for and gain a stack of Royal Chum, protecting the waters around you from Corrupted Ghoulfish and increasing the likelihood to catch Queen's Lurefish for 30 sec.\n\nThrowing multiple Regal Dottyback can extend this buff up to 10 min." }
entries[456588] = { ["name"] = "Isle of Dorn", ["text"] = "Instant\nRecommended Skill: 1\n\nCalm seas and familiar conditions make this area perfect for Anglers looking to practice their ability before delving deeper into Khaz Algar.\n\nPools found in this zone:\n- Glimmerpool\n- Shore Treasure\n- Stargazer Swarm\n- Festering Rotpool\n- Calm Surfacing Ripple\n- River Bass Pool\n- Bloody Perch Swarm\nProfession:\nFishing (1)" }
entries[456589] = { ["name"] = "The Ringing Deeps", ["text"] = "Instant\nRecommended Skill: 125\n\nA cave system highlighted by the marriage of industry and adaptation. Its rivers teem with all kinds of life from above and below.\n\nPools found in this zone:\n- Glimmerpool\n- Calm Surfacing Ripple\n- River Bass Pool\n- Anglerseeker Torrent\n- Floating Deep Treasure\nProfession:\nFishing (75)" }
entries[456590] = { ["name"] = "Hallowfall", ["text"] = "Instant\nRecommended Skill: 225\n\nAn area surprisingly capable of sustaining all sorts of life. Deep chasms and vast underground rivers make it a crossroads for Anglers to test their skill.\n\nPools found in this zone:\n- Calm Surfacing Ripple\n- Glimmerpool\n- Anglerseeker Torrent\n- Floating Deep Treasure\n- Infused Ichor Spill\n- Whispers of the Deep\n- Royal Ripple\n- Blood in the Water\nProfession:\nFishing (150)" }
entries[456591] = { ["name"] = "Azj-Kahet", ["text"] = "Instant\nRecommended Skill: 375\n\nSparse waters coagulated with the ichor of all sorts of oddities. Especially challenging to traverse for an ill-prepared Angler.\n\nPools found in this zone:\n- Calm Surfacing Ripple\n- Glimmerpool\n- Infused Ichor Spill\n- Royal Ripple\n- Swarm of Slum Sharks\n- Whispers of the Deep\nProfession:\nFishing (225)" }
entries[456592] = { ["name"] = "Huskfish Treasure", ["text"] = "Instant\nOpen the contents of the Huskfish's stomach." }
